window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cc9156907e8bc7a9"]={"versions": [{"id": "FIG-cc9156907e8bc7a9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-2-Metamodell-Klassendiagramm aus dem AUTOSAR Template Modeling Guide zur Spezifikation der Definitionsstruktur von Aufzählungstypen (Enumerations). Es stellt die metamodellbasierte Verankerung und Komposition von Aufzählungen und ihren zugehörigen Literalen gemäß UML-2-Superstruktur im Rahmen der AUTOSAR-M2-Modellierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Assoziation:</p>\n<ul class=\"fig-list\">\n<li><code>DataType</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>Enumeration</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» Enumeration</code> mit Supertyp <code>DataType</code>).</li>\n<li><code>InstanceSpecification</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>EnumerationLiteral</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» EnumerationLiteral</code> mit Supertyp <code>InstanceSpecification</code>).</li>\n<li>Kompositionsbeziehung: Eine gerichtete/bidirektionale Komposition (gefüllte Raute auf Seiten von <code>Enumeration</code>).</li>\n<li>Rollenname <code>+enumeration</code> mit Multiplizität <code>0..1</code> an der Metaklasse <code>Enumeration</code>.</li>\n<li>Rollenname <code>+ownedLiteral</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> an der Metaklasse <code>EnumerationLiteral</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm spezifiziert das Schaubild keinen dynamischen Ablauf und keine Sequenzen. Es definiert die statische Eigentümer- und Enthaltenseins-Beziehung, nach der eine <code>Enumeration</code> eine geordnete Menge von <code>EnumerationLiteral</code>-Instanzen besitzt (<code>ownedLiteral</code>). Ein Literal ist dabei höchstens einer Enumeration zugeordnet (<code>0..1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert die normative Abbildung von Aufzählungstypen im AUTOSAR-Metamodell auf standardisierte UML-2-Konzepte:</p>\n<ul class=\"fig-list\">\n<li>Modellierer und Tool-Entwickler müssen Aufzählungswerte als geordnete Sequenz (<code>{ordered}</code>) von Literalen innerhalb des Aufzählungstyps führen.</li>\n<li>Jedes <code>EnumerationLiteral</code> existiert als spezifische Ausprägung von <code>InstanceSpecification</code> im Eigentum (<code>ownedLiteral</code>) des umschließenden <code>Enumeration</code>-Datentyps.</li>\n<li>Bei der Generierung von Schemata (XSD) oder Code-Artefakten ist die durch <code>{ordered}</code> festgelegte Reihenfolge der Literale zwingend zu bewahren.</li>\n</ul>"}, {"id": "FIG-81ae455294215797", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-2-Metamodell-Klassendiagramm aus dem AUTOSAR Template Modeling Guide zur Spezifikation der Definitionsstruktur von Aufzählungstypen (Enumerations). Es stellt die metamodellbasierte Verankerung und Komposition von Aufzählungen und ihren zugehörigen Literalen gemäß UML-2-Superstruktur im Rahmen der AUTOSAR-M2-Modellierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Assoziation:</p>\n<ul class=\"fig-list\">\n<li><code>DataType</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>Enumeration</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» Enumeration</code> mit Supertyp <code>DataType</code>).</li>\n<li><code>InstanceSpecification</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>EnumerationLiteral</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» EnumerationLiteral</code> mit Supertyp <code>InstanceSpecification</code>).</li>\n<li>Kompositionsbeziehung: Eine gerichtete/bidirektionale Komposition (gefüllte Raute auf Seiten von <code>Enumeration</code>).</li>\n<li>Rollenname <code>+enumeration</code> mit Multiplizität <code>0..1</code> an der Metaklasse <code>Enumeration</code>.</li>\n<li>Rollenname <code>+ownedLiteral</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> an der Metaklasse <code>EnumerationLiteral</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm spezifiziert das Schaubild keinen dynamischen Ablauf und keine Sequenzen. Es definiert die statische Eigentümer- und Enthaltenseins-Beziehung, nach der eine <code>Enumeration</code> eine geordnete Menge von <code>EnumerationLiteral</code>-Instanzen besitzt (<code>ownedLiteral</code>). Ein Literal ist dabei höchstens einer Enumeration zugeordnet (<code>0..1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert die normative Abbildung von Aufzählungstypen im AUTOSAR-Metamodell auf standardisierte UML-2-Konzepte:</p>\n<ul class=\"fig-list\">\n<li>Modellierer und Tool-Entwickler müssen Aufzählungswerte als geordnete Sequenz (<code>{ordered}</code>) von Literalen innerhalb des Aufzählungstyps führen.</li>\n<li>Jedes <code>EnumerationLiteral</code> existiert als spezifische Ausprägung von <code>InstanceSpecification</code> im Eigentum (<code>ownedLiteral</code>) des umschließenden <code>Enumeration</code>-Datentyps.</li>\n<li>Bei der Generierung von Schemata (XSD) oder Code-Artefakten ist die durch <code>{ordered}</code> festgelegte Reihenfolge der Literale zwingend zu bewahren.</li>\n</ul>"}, {"id": "FIG-c9a6ab1b76cfda93", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-2-Metamodell-Klassendiagramm aus dem AUTOSAR Template Modeling Guide zur Spezifikation der Definitionsstruktur von Aufzählungstypen (Enumerations). Es stellt die metamodellbasierte Verankerung und Komposition von Aufzählungen und ihren zugehörigen Literalen gemäß UML-2-Superstruktur im Rahmen der AUTOSAR-M2-Modellierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen und deren Assoziation:</p>\n<ul class=\"fig-list\">\n<li><code>DataType</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>Enumeration</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» Enumeration</code> mit Supertyp <code>DataType</code>).</li>\n<li><code>InstanceSpecification</code>: Abstrakte bzw. übergeordnete Metaklasse, von der <code>EnumerationLiteral</code> abgeleitet ist (dargestellt als Metaklasse <code>«metaclass» EnumerationLiteral</code> mit Supertyp <code>InstanceSpecification</code>).</li>\n<li>Kompositionsbeziehung: Eine gerichtete/bidirektionale Komposition (gefüllte Raute auf Seiten von <code>Enumeration</code>).</li>\n<li>Rollenname <code>+enumeration</code> mit Multiplizität <code>0..1</code> an der Metaklasse <code>Enumeration</code>.</li>\n<li>Rollenname <code>+ownedLiteral</code> mit Multiplizität <code>*</code> und Eigenschaft <code>{ordered}</code> an der Metaklasse <code>EnumerationLiteral</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm spezifiziert das Schaubild keinen dynamischen Ablauf und keine Sequenzen. Es definiert die statische Eigentümer- und Enthaltenseins-Beziehung, nach der eine <code>Enumeration</code> eine geordnete Menge von <code>EnumerationLiteral</code>-Instanzen besitzt (<code>ownedLiteral</code>). Ein Literal ist dabei höchstens einer Enumeration zugeordnet (<code>0..1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dokumentiert die normative Abbildung von Aufzählungstypen im AUTOSAR-Metamodell auf standardisierte UML-2-Konzepte:</p>\n<ul class=\"fig-list\">\n<li>Modellierer und Tool-Entwickler müssen Aufzählungswerte als geordnete Sequenz (<code>{ordered}</code>) von Literalen innerhalb des Aufzählungstyps führen.</li>\n<li>Jedes <code>EnumerationLiteral</code> existiert als spezifische Ausprägung von <code>InstanceSpecification</code> im Eigentum (<code>ownedLiteral</code>) des umschließenden <code>Enumeration</code>-Datentyps.</li>\n<li>Bei der Generierung von Schemata (XSD) oder Code-Artefakten ist die durch <code>{ordered}</code> festgelegte Reihenfolge der Literale zwingend zu bewahren.</li>\n</ul>"}], "trans": [{"from": "FIG-cc9156907e8bc7a9", "to": "FIG-81ae455294215797", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-81ae455294215797", "to": "FIG-c9a6ab1b76cfda93", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c9a6ab1b76cfda93", "to": "FIG-81ae455294215797", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
